const pageImageTasksByUser = `-- name: PageImageTasksByUser :many
SELECT
  id, task_id, user_id, project_id, prompt, prompt_template_id,
  COALESCE(ref_image_urls, CAST('null' AS JSON)) AS ref_image_urls,
  ratio, resolution, aspect_ratio, width, height, count, success_count, status,
  error_msg, model_id, workflow_version_id, category, owner_type, owner_id, deleted,
  create_time, update_time
FROM afv_image_task
WHERE user_id = ? AND deleted = 0
ORDER BY id DESC
LIMIT ? OFFSET ?
`

type PageImageTasksByUserParams struct {
	UserID int64 `json:"user_id"`
	Limit  int32 `json:"limit"`
	Offset int32 `json:"offset"`
}

func (q *Queries) PageImageTasksByUser(ctx context.Context, arg PageImageTasksByUserParams) ([]AfvImageTask, error) {
	rows, err := q.db.QueryContext(ctx, pageImageTasksByUser, arg.UserID, arg.Limit, arg.Offset)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []AfvImageTask{}
	for rows.Next() {
		var i AfvImageTask
		if err := rows.Scan(
			&i.ID,
			&i.TaskID,
			&i.UserID,
			&i.ProjectID,
			&i.Prompt,
			&i.PromptTemplateID,
			&i.RefImageUrls,
			&i.Ratio,
			&i.Resolution,
			&i.AspectRatio,
			&i.Width,
			&i.Height,
			&i.Count,
			&i.SuccessCount,
			&i.Status,
			&i.ErrorMsg,
			&i.ModelID,
			&i.WorkflowVersionID,
			&i.Category,
			&i.OwnerType,
			&i.OwnerID,
			&i.Deleted,
			&i.CreateTime,
			&i.UpdateTime,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

